pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract RatioOverflowTest is Test {
    function testComputeRatioX96OverflowReturnsZero() public pure {
        // Craft amounts where sqrt(amount1/amount0) * 2^96 > uint160.max
        uint256 largeAmount1 = 2**255;
        uint256 smallAmount0 = 1;
        uint160 result = SqrtPriceCalculator.computeRatioX96(largeAmount1, smallAmount0);
        assertEq(result, 0, 'Overflow should return 0');
    }

    function testValidateHandlerOrderPassesWhenNoBoundsSet() public {
        // HANDLER_ORDER_VALIDATE_FLAG set in AMM, but no pricing bounds in hook
        // bounds.isSet = false => validateHandlerOrder is a no-op
        vm.prank(attacker);
        // Order at absurd price: 1 tokenA for 1e30 tokenB
        handler.openOrder(groupKey, extremePrice, 1, deadline, hookData);
        // Should succeed — no bounds to enforce
        assertTrue(handler.getOrder(orderId).isActive,
            'Order at extreme price passes when bounds not configured');
    }
}

