    function testNestedDirectSwapClobbersOuterBeforeSwapAmount() public {
        // Outer swap: 1000 tokens
        // Inner swap (triggered by malToken transfer): 1 token
        // Pricing bounds: validate amount matches beforeSwap amount

        // outerBeforeSwap: tstore[SLOT] = 1000
        // malToken.transfer() triggers innerSwap:
        //   innerBeforeSwap: tstore[SLOT] = 1  <-- clobbers 1000
        //   innerAfterSwap: reads 1, validates 1 == 1 -> OK
