pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract DoubleRoundingTest is Test {
    function testDoubleRoundingInflatesReconstructedPrice() public pure {
        uint160 sqrtP = 79228162514264337593543950336; // ~1:1 price in Q96
        uint256 amountIn = 1e18 + 1; // odd amount triggers rounding

        uint256 amountOut = CLOBHelper.calculateFixedInput(amountIn, sqrtP);
        uint160 reconstructed = SqrtPriceCalculator.computeRatioX96(amountOut, amountIn);

        // Double rounding: reconstructed >= sqrtP
        assertGe(reconstructed, sqrtP,
            'Double rounding should inflate reconstructed price');
    }

    function testOrderJustBelowMinBoundsPassesDueToDoubleRounding() public {
        uint160 minPrice = 79228162514264337593543950336;
        hook.registryUpdatePricingBounds(tokenA, tokenB, minPrice, minPrice * 2);

        // Order at minPrice - 1 (below min, should be rejected)
        // But double rounding inflates reconstructed price to >= minPrice
        vm.prank(attacker);
        // If this succeeds: double rounding bypass confirmed
        handler.openOrder(groupKey, minPrice - 1, 1e18 + 1, deadline, hookData);
        assertTrue(handler.getOrder(orderId).isActive,
            'Order below min price passed due to double rounding inflation');
    }
}

