import 'forge-std/Test.sol';

contract FlagDesynTest is Test {
    function testHandlerOrderValidateWithoutBoundsIsNoop() public {
        // Set HANDLER_ORDER_VALIDATE_FLAG in AMM packed token settings
        uint256 packedSettings = TOKEN_SETTINGS_HANDLER_ORDER_VALIDATE_FLAG; // 1 << 9
        vm.prank(tokenAdmin);
        amm.setTokenSettings(tokenA, packedSettings);

        // Do NOT call hook.registryUpdatePricingBounds -> bounds.isSet = false

        // Open order at absurd price: 1 tokenA for 1e30 tokenB
        uint160 extremePrice = type(uint160).max - 1;
        vm.prank(attacker);
        handler.openOrder(groupKey, extremePrice, 1, deadline, hookData);

        // Order should be accepted — validateHandlerOrder called but bounds check skipped
        assertTrue(handler.getOrder(orderId).isActive,
            'Order at extreme price passes: HANDLER_ORDER_VALIDATE_FLAG set but no bounds configured');
    }
}

