pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract DeadCodeBoundsTest is Test {
    function testBoundaryValueConsistencyAtMin() public {
        uint160 minPrice = 79228162514264337593543950336;
        uint160 maxPrice = minPrice * 2;
        hook.registryUpdatePricingBounds(tokenA, tokenB, minPrice, maxPrice);

        // Test at EXACTLY minPrice — both blocks execute if isSet=true
        vm.prank(user);
        bool successAtMin;
        try handler.openOrder(groupKey, minPrice, 1e18, deadline, hookData) {
            successAtMin = true;
        } catch {
            successAtMin = false;
        }

        // Test at minPrice - 1 (should always reject)
        vm.prank(attacker);
        bool successBelowMin;
        try handler.openOrder(groupKey, minPrice - 1, 1e18, deadline, hookData) {
            successBelowMin = true;
        } catch {
            successBelowMin = false;
        }

        // If successBelowMin=true: dead code in second isSet block allows bypass
        assertFalse(successBelowMin, 'Order below minPrice should always be rejected');
        emit log_named_bool('Order at exact minPrice accepted', successAtMin);
    }
}
